$ErrorActionPreference='Stop'
$js=@'
let ws;try{
const tabs=await(await fetch("http://127.0.0.1:17447/json/list")).json();const t=tabs.find(x=>x.id==="251BEB4F668E7ADF5400D3821089D3F6"&&x.url.startsWith("https://www.avito.ru/krasnoyarsk/"));if(!t)throw Error("NOT_FOUND");
ws=new WebSocket(t.webSocketDebuggerUrl);
const result=await Promise.race([new Promise((ok,no)=>{
ws.addEventListener("open",()=>ws.send(JSON.stringify({id:99,method:"Runtime.evaluate",params:{expression:"window.scrollTo(0,1000);window.scrollY",returnByValue:true}})),{once:true});
ws.addEventListener("message",e=>{let x=JSON.parse(e.data);if(x.id===99)ok({value:x.result?.result?.value||0,error:x.error?.code||null})});
ws.addEventListener("error",no,{once:true})
}),new Promise((_,bad)=>setTimeout(()=>bad(Error("TIMEOUT")),4500))]);
console.log(JSON.stringify(result))
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,100)}))}
if(ws)ws.close();process.exit(0)
'@
$tmp=Join-Path $env:TEMP 'avito-scroll-150.mjs'
try{[System.IO.File]::WriteAllText($tmp,$js,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item $tmp -Force -ErrorAction SilentlyContinue}
